import * as THREE from '../vendor/three.module.js';import {BODIES,footprint} from './architecture.js';import {groupPose} from './pose.js';import {DIAGNOSTIC_COLORS,fixedEquipment} from './transport-audit.js';
export function renderDiagnostics(v){if(!v.diagnosticGroup){if(!v.diagnosticsEnabled)return;v.diagnosticGroup=new THREE.Group();v.scene.add(v.diagnosticGroup);v.diagnosticRows=[];for(const b of BODIES){const g=new THREE.Group();g.userData.diagnosticId=b.id;v.diagnosticGroup.add(g);const material=new THREE.LineBasicMaterial({color:'#318b76',depthTest:false,transparent:true,opacity:.8});for(const[x,z]of b.cells){const m=new THREE.LineSegments(new THREE.EdgesGeometry(new THREE.BoxGeometry(8,6,8)),material);m.position.set(x*8+4,3,z*8+4);m.userData.diagnosticId=b.id;m.renderOrder=10;g.add(m);}v.diagnosticRows.push({id:b.id,g,material,mobile:true});}for(const q of fixedEquipment()){const m=new THREE.LineSegments(new THREE.EdgesGeometry(new THREE.BoxGeometry(q.w,q.h??6,q.d)),new THREE.LineBasicMaterial({color:DIAGNOSTIC_COLORS.fixed,depthTest:false,transparent:true,opacity:.75}));m.position.set(q.x+q.w/2,q.y+(q.h??6)/2,q.z+q.d/2);m.userData.diagnosticId=q.id;m.renderOrder=10;v.diagnosticGroup.add(m);v.diagnosticRows.push({id:q.id,g:m,material:m.material,mobile:false,y:q.y});}}
 v.diagnosticGroup.visible=!!v.diagnosticsEnabled&&v.mode==='overview';if(!v.diagnosticGroup.visible)return;const by=new Map(v.diagnosticAudit?.records.map(r=>[r.id,r])??[]);for(const r of v.diagnosticRows){const p=v.sim.positions[r.id];if(r.mobile)groupPose(r.g,p);r.g.visible=v.floor==='all'||(r.mobile?Math.abs(p.y-Number(v.floor))<.1:Math.abs(r.y-Number(v.floor))<.1||r.id.includes('EV'));const data=by.get(r.id),active=data&&(data.transitions[v.sim.phase].distance>.001||data.transitions[v.sim.phase].rotation>.001);r.material.color.set(r.id===v.diagnosticSelected?'#ffffff':r.mobile?DIAGNOSTIC_COLORS[data?.classification??'waiting']:DIAGNOSTIC_COLORS.fixed);r.material.opacity=r.id===v.diagnosticSelected?1:active?.95:.45;}
}
export function pickDiagnostic(v,x,y){if(!v.diagnosticGroup?.visible)return null;const r=v.renderer.domElement.getBoundingClientRect(),ray=new THREE.Raycaster();ray.params.Line.threshold=.2;ray.setFromCamera(new THREE.Vector2((x-r.left)/r.width*2-1,-(y-r.top)/r.height*2+1),v.camera);for(const hit of ray.intersectObjects([...Object.values(v.groups),...v.diagnosticGroup.children],true)){let visible=true,id=null;for(let q=hit.object;q;q=q.parent){if(!q.visible)visible=false;if(q.userData.diagnosticId)id=q.userData.diagnosticId;}if(visible&&id)return id;}return null;}
